xinshengCustomCss:
/* =========================================================
   糯叽机日记卡片 CSS · v8
   ---------------------------------------------------------
   请整份替换旧 CSS。
   此版不再使用代理按钮。
   五个真实按钮由 JS 直接 fixed 到卡片顶部。
   ========================================================= */


/* =========================
   卡片
   ========================= */

.xt-root {
    --xt-yellow: #eab308;

    position: relative !important;

    background: #fff !important;
    color: #333 !important;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Helvetica Neue",
        Arial,
        sans-serif !important;

    border: none !important;
    border-radius: 16px !important;

    box-shadow:
        0 4px 20px
        rgba(0, 0, 0, .08) !important;

    /* 顶部真实按钮区域 */
    padding-top: 58px !important;

    padding-bottom: 20px !important;

    box-sizing: border-box !important;
}


/* =========================
   通用文字
   ========================= */

.xt-text {
    display: block;

    background: transparent !important;
    border: none !important;
    box-shadow: none !important;

    padding: 0 !important;

    color: #333;

    font-size: 15px;

    margin-bottom: 16px;

    box-sizing: border-box;
}


/* =========================================================
   原站五个真实按钮
   ---------------------------------------------------------
   不复制
   不隐藏
   不改 DOM 父子关系
   只是改变它们的视觉位置
   ========================================================= */

.xt-relocated-native-action {
    position: fixed !important;

    left:
        var(--xt-native-left)
        !important;

    top:
        var(--xt-native-top)
        !important;

    width: 28px !important;
    height: 28px !important;

    min-width: 28px !important;
    min-height: 28px !important;

    margin: 0 !important;
    padding: 0 !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    background: transparent !important;

    border: none !important;
    border-radius: 0 !important;

    box-shadow: none !important;

    color: #eab308 !important;

    cursor: pointer !important;

    z-index: 2147483000 !important;

    box-sizing: border-box !important;

    transform: none !important;
}


/* 图标尺寸 */
.xt-relocated-native-action svg {
    display: block !important;

    width: 21px !important;
    height: 21px !important;

    stroke: currentColor !important;

    pointer-events: none !important;
}


/* × */
.xt-relocated-native-action[
    data-xt-native-action="close"
] svg {
    width: 22px !important;
    height: 22px !important;
}


/* 删除 */
.xt-relocated-native-action[
    data-xt-native-action="delete"
] {
    color: #e57373 !important;
}


/* 点击反馈 */
.xt-relocated-native-action:active {
    opacity: .45 !important;
    transform: scale(.88) !important;
}


/* 原来底部工具栏的父容器只收掉空白。
   不隐藏父容器，不影响按钮事件。 */
.xt-native-toolbar-shell {
    height: 0 !important;
    min-height: 0 !important;

    margin-top: 0 !important;
    margin-bottom: 0 !important;

    padding-top: 0 !important;
    padding-bottom: 0 !important;

    overflow: visible !important;
}


/* =========================================================
   日期在上
   ========================================================= */

.xt-text:nth-of-type(1) {
    position: relative !important;

    display: block !important;

    text-align: center !important;

    font-size: 12px !important;

    color: #8e8e93 !important;

    margin-top: 4px !important;

    margin-bottom: 55px !important;
}


/* 标题 */
.xt-text:nth-of-type(1)::after {
    content: "我的小海葵" !important;

    position: absolute !important;

    left: 9px !important;

    bottom: -45px !important;

    font-size: 24px !important;

    line-height: 30px !important;

    font-weight: 700 !important;

    color: #000 !important;

    white-space: nowrap !important;
}


/* =========================================================
   天气
   ========================================================= */

.xt-text:nth-of-type(2) {
    display: inline-block !important;

    font-size: 14px !important;

    margin-left: 14px !important;

    margin-bottom: 16px !important;

    color: #666 !important;
}


.xt-text:nth-of-type(2)::before {
    content: "" !important;

    display: inline-block !important;

    width: 4px !important;
    height: 15px !important;

    background: #d1d1d6 !important;

    border-radius: 2px !important;

    margin-right: 8px !important;

    vertical-align: -3px !important;
}


.xt-text:nth-of-type(2)::after {
    content: " | " !important;

    margin: 0 2px !important;

    position: relative !important;

    top: -1px !important;
}


/* =========================================================
   温度
   ========================================================= */

.xt-text:nth-of-type(3) {
    display: inline-block !important;

    font-size: 14px !important;

    color: #666 !important;

    margin-left: 2px !important;

    margin-bottom: 16px !important;
}


/* =========================================================
   正文
   ========================================================= */

.xt-text:nth-of-type(4) {
    display: block !important;

    line-height: 1.6 !important;

    margin-left: 14px !important;

    margin-right: 16px !important;

    margin-bottom: 16px !important;

    color: #444 !important;
}


/* =========================================================
   标签
   ========================================================= */

.xt-text:nth-of-type(5),
.xt-text:nth-of-type(6) {
    display: inline-block !important;

    color: #eab308 !important;

    margin-left: 12px !important;

    margin-right: -7px !important;

    margin-bottom: 24px !important;
}


.xt-text:nth-of-type(5)::before {
    content: "#" !important;
}


/* =========================================================
   待办 1
   ========================================================= */

.xt-text:nth-of-type(7) {
    position: relative !important;

    display: block !important;

    padding-left: 34px !important;

    margin-left: 11px !important;

    margin-top: 28px !important;

    margin-bottom: 12px !important;

    color: #8e8e93 !important;

    text-decoration: line-through !important;
}


.xt-text:nth-of-type(7)::before {
    content: "待办事项" !important;

    position: absolute !important;

    left: 2px !important;

    top: -35px !important;

    font-size: 18px !important;

    font-weight: 700 !important;

    color: #000 !important;

    text-decoration: none !important;
}


.xt-text:nth-of-type(7)::after {
    content: "" !important;

    position: absolute !important;

    left: 4px !important;

    top: 3px !important;

    width: 20px !important;

    height: 20px !important;

    border:
        1.5px solid
        #d1d1d6 !important;

    border-radius: 50% !important;

    box-sizing: border-box !important;
}


/* =========================================================
   待办 2
   ========================================================= */

.xt-text:nth-of-type(8) {
    position: relative !important;

    display: block !important;

    padding-left: 34px !important;

    margin-left: 11px !important;

    margin-bottom: 60px !important;

    color: #444 !important;
}


.xt-text:nth-of-type(8)::before {
    content: "✓" !important;

    position: absolute !important;

    left: 4px !important;

    top: 2px !important;

    width: 20px !important;

    height: 20px !important;

    background: #eab308 !important;

    color: #fff !important;

    font-size: 12px !important;

    font-weight: 700 !important;

    line-height: 20px !important;

    text-align: center !important;

    border-radius: 50% !important;
}


/* =========================================================
   actionHint
   ========================================================= */

.xt-text:nth-of-type(9) {
    margin-left: 14px !important;

    margin-right: 16px !important;
}


/* =========================================================
   当前环境
   ========================================================= */

.xt-text:nth-of-type(10) {
    position: relative !important;

    display: block !important;

    background: #f2f2f7 !important;

    border-radius: 12px !important;

    padding:
        36px
        16px
        12px
        16px !important;

    margin-top: -5px !important;

    margin-bottom: 60px !important;

    font-size: 14px !important;

    line-height: 1.7 !important;

    color: #8e8e93 !important;
}


.xt-text:nth-of-type(10)::before {
    content: "当前环境" !important;

    position: absolute !important;

    top: 12px !important;

    left: 16px !important;

    font-size: 15px !important;

    font-weight: 600 !important;

    color: #000 !important;
}


/* =========================================================
   卡片底部黄色四图标
   ========================================================= */

.xt-text:nth-of-type(10)::after {
    content: "" !important;

    position: absolute !important;

    bottom: -50px !important;

    left: 0 !important;

    width: 100% !important;

    height: 32px !important;

    background-image:
        url("https://nos.netease.com/ysf/7f6e0c662c417d87d0a01670d98fc3d8.jpeg"),
        url("https://nos.netease.com/ysf/9c4e0b6658bec04188727cf8e750700e.jpeg"),
        url("https://nos.netease.com/ysf/b389f00f9375cd739ec05ac0997b3dbe.jpeg"),
        url("https://nos.netease.com/ysf/5672f34cc5ba38b7a4ab5ba721164ea0.jpeg") !important;

    background-position:
        2% center,
        33% center,
        66% center,
        98% center !important;

    background-size:
        42px 45px,
        52px 50px,
        47px 52px,
        55px 51px !important;

    background-repeat:
        no-repeat !important;

    pointer-events:
        none !important;
}

